import { Avatar, Box, Stack, SxProps, Typography } from '@mui/material';
import { useFragment } from 'react-relay';
import { BlogThumbnail_data$key } from './__generated__/BlogThumbnail_data.graphql';

// import 
const graphql = require('babel-plugin-relay/macro');

interface BlogThumbnailProps {
    fragRef: BlogThumbnail_data$key;
    onClick: (id?: string) => void;
    sx?: SxProps;
};

export const fragQuery = graphql`
    fragment BlogThumbnail_data on BlogType {
        id
        title 
        description
        cover
        icon
    }
`;

function BlogThumbnail({ fragRef, onClick, sx }: BlogThumbnailProps) {

    const data = useFragment(fragQuery, fragRef)

    return (
        <Box
            component="a"
            key={data?.id}
            sx={[{
                borderRadius: "12px",
                p: 1,
                m: 1,
                boxShadow: theme => `0px 0px 5px 5px ${theme.palette.background.paper}`,
                backgroundColor: theme => theme.palette.background.default,
                cursor: "pointer",
                transition: "all 0.2s ease-in-out",
                justifyContent: "space-evenly",
                display: "flex",
                flexDirection: "column",
            },
            ...(Array.isArray(sx) ? sx : [sx])
            ]}
            onClick={() => onClick(data.id)}
        >
            <Stack gap={1} direction='row' p={0.5} flex={1} flexShrink={1} >
                {data?.icon && <Avatar src={data?.icon} alt={data?.title} />}
                <Typography variant="subtitle1" children={data?.title} color="text.primary"
                    sx={{
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                        lineHeight: "1.5rem",
                        maxLines: 1
                    }}
                />
            </Stack>

            <Box
                sx={{
                    display: "flex",
                    width: "100%",
                    borderRadius: "12px",
                    overflow: "hidden",
                    backgroundColor: theme => theme.palette.background.paper,
                }}
            >
                <img
                    src={data?.cover ?? "https://source.unsplash.com/random"}
                    alt={data?.title + " cover "}
                    style={{
                        flex: 1,
                        flexGrow: 1,
                        width: "100%",
                    }}
                />
            </Box>

        </Box>
    );

};

export default BlogThumbnail;
