import { Box } from '@mui/material';

// theme wrapper
import ThemeWrapper from '../theme/Wrapper';
import ToggleThemeStack from './ToggleThemeStack';
import Footer from './Footer';
import Content from './Content';
import prodEnv, { devEnv } from '../relay/environment';
import { RelayEnvironmentProvider } from 'react-relay';
import { RouterProvider, createBrowserRouter } from 'react-router-dom';
import Blog from './Blog';


const Portfolio: React.FC = () => {

    return (
        <Box
            sx={{
                display: 'flex',
                placeItems: 'center',
                minHeight: "600px",
                height: '100vh',
                backgroundColor: 'background.default',
                width: '100vw',
                flexDirection: 'column',
                px: 0,
                overflowX: 'hidden',
                overflowY: 'scroll',
                transition: 'background-color 500ms ease-in-out',

                "&::-webkit-scrollbar": {
                    display: "none"
                }
            }}
        >

            <Helmet>
                <title>Jainam Shah | Full Stack Developer </title>
                <meta
                    name="description"
                    content="Showcase of my skills as a full stack developer and mobile app developer. Explore my projects, experience, and expertise in web and mobile development."
                />
                <meta
                    name="keywords"
                    content="Full stack developer, mobile app developer, web development, mobile development, programming, front-end development, back-end development, JavaScript, HTML, CSS, Android, iOS, portfolio"
                />
                <meta
                    name="author"
                    content="Jainam Shah"
                />
            </Helmet>

            <ToggleThemeStack />
            <Content />
            <Footer />

        </Box >
    );
};

const router = createBrowserRouter([
    {
        path: '/',
        element: <Portfolio />
    },
    {
        path: '/blog/:id',
        element: <Blog />
    }
]);

function RootAppWrapper() {
    const environment = process.env.NODE_ENV === 'development' ?
        devEnv({ "extendedUrl": "blogs/graphql/" })
        : prodEnv({
            "apiToken": "468da0934b3ab027cdc8d00a96c33f9b9fc57391556749d2c4cc584f0c378367",
            "url": "https://api.jaesmetaverse.com/blogs/graphql/"
        })

    return (
        <ThemeWrapper>
            <RelayEnvironmentProvider environment={environment}>
                <RouterProvider router={router} />
            </RelayEnvironmentProvider>
        </ThemeWrapper>
    )
};

export default RootAppWrapper;
