import React from 'react';
import { Box, Skeleton, Stack } from '@mui/material';
import { useLazyLoadQuery } from 'react-relay';
import { useNavigate } from 'react-router';
import BlogThumbnail from './BlogThumbnail';
import { ListingBlogsQuery } from './__generated__/ListingBlogsQuery.graphql';

const graphql = require('babel-plugin-relay/macro');


function BlogListing() {
    const navigate = useNavigate();
    const data = useLazyLoadQuery<ListingBlogsQuery>(
        graphql`
            query ListingBlogsQuery {
                blogs {
                    edges {
                        node {
                            id  
                            ...BlogThumbnail_data
                        }
                    }
                }
            }
        `,
        {},
        { "fetchPolicy": "store-and-network" }
    );

    return (
        <Box
            sx={{
                display: 'flex',
                height: "90%",
                padding: "10px",
                marginRight: "20px"
            }}
        >
            <Stack direction="column" flexWrap="wrap" justifyContent="space-between" >
                {data?.blogs?.edges?.map((edge, index) => (
                    <BlogThumbnail
                        key={edge?.node?.id ?? index}
                        fragRef={edge?.node as any}
                        onClick={id => navigate(`/blog/${id}`)}
                        sx={{
                            maxWidth: "400px",
                            width: "90vw",
                            height: "max-content",
                            maxHeight: "45%",
                            marginRight: 1.5
                        }}
                    />
                ))}
            </Stack>

        </Box>
    );

};

export default function Listings() {
    return (
        <React.Suspense fallback={<Skeleton variant="rounded" height="200px" width="150px" />}>
            <BlogListing />
        </React.Suspense>
    );
};
