import { Stack, Typography } from '@mui/material';
import BaseCard from '../BaseCard';
import { ArrowRightAlt } from '@mui/icons-material';

interface LinkCardProps {
    link: string;
    title: string;
};

export const LinkCard = ({ link, title }: LinkCardProps) => (
    <BaseCard
        sx={{
            height: "27%",
            width: "70vw",
            p: 2,
            alignItems: "center",
            justifyContent: "center",
            maxWidth: "300px"
        }}
        onClick={() => window.open(link, '_blank')}
        children={
            <Typography variant="overline" textAlign="center" >
                <ArrowRightAlt sx={{ rotate: "-30deg", position: "absolute", bottom: "10px", right: "10px" }} />
                {title.split('\n').map((text, index) => (
                    <span key={index} style={{ display: "block" }}>{text}</span>
                ))}
            </Typography>
        }
    />
);

function Links() {

    return (
        <Stack
            direction="column"
            gap={2}
            sx={{
                height: "100%",
                width: "auto",
                mx: 2,
                p: 2,
                justifyContent: "space-evenly",
                alignItems: "center",
            }}>

            <LinkCard
                title='JuteBox 📻'
                link='https://card.jaesmetaverse.com/mini-player'
            />
            <LinkCard
                title='Rick and Morty 🤖'
                link='https://card.jaesmetaverse.com/rick-morty-loader/'
            />
            <LinkCard
                title='Bouncy Clock ⏰'
                link='https://card.jaesmetaverse.com/clock'
            />


        </Stack>
    );

};

export default Links;
